// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // Fuzz parameters: actor (caller) and amount (value sent). The general rule:
    // after addToBalance() completes, getBalance(actor) increased by amount.
    // This holds for the reference, but the mutant that writes to address(0) breaks it
    // for some inputs (e.g., any nonzero amount).
    function testFuzz_property(address actor, uint256 amount) public {
        // keep actor non-zero to be a realistic caller EOA; allow zero as well but it's fine
        vm.assume(actor != address(0));
        // avoid sending dust out of range: bound amount to reasonable ETH range but keep wide
        amount = bound(amount, 0, 1 ether);

        // record balance before
        uint256 before = c.getBalance(actor);

        // fund the actor so they can send amount
        vm.deal(actor, amount);
        vm.startPrank(actor);
        // call payable function
        c.addToBalance{value: amount}();
        vm.stopPrank();

        uint256 after = c.getBalance(actor);

        // The single assertion: for the correct contract, after == before + amount for ALL inputs.
        // The mutant that increments address(0) instead will fail this for some inputs (any nonzero amount).
        assertTrue(after == before + amount);
    }
}

