pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address actor, uint256 amount) public {
        // keep amount reasonable but allow zero too
        amount = bound(amount, 0, 1 ether);
        // fund actor so they can send amount
        vm.deal(actor, amount);
        // record prior balance via getter
        uint256 before = c.getBalance(actor);
        // perform the payable call as actor
        vm.prank(actor);
        c.addToBalance{value: amount}();
        // exactly one assertion: caller's balance increased by amount
        uint256 afterBal = c.getBalance(actor);
        assertTrue(afterBal == before + amount);
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    // fuzzed params: attacker initial funding and a separate victim address
    function testFuzz_property(uint256 attackFund, address victim) public {
        // keep amounts reasonable but wide
        attackFund = bound(attackFund, 1, 1 ether);
        // victim must be nonzero and not the contract address
        vm.assume(victim != address(0) && victim != address(this) && victim != address(c));

        // deploy reentrant attacker that will call addToBalance and re-enter during receive
        ReentrantAttacker attacker = new ReentrantAttacker(address(c));

        // fund attacker externally
        vm.deal(address(attacker), attackFund);

        // perform the attack: attacker calls addToBalance sending attackFund
        bool ok;
        try attacker.attack{value: attackFund}() {
            ok = true;
        } catch {
            ok = false;
        }

        // After the call completes, in the correct contract the attacker's recorded balance must equal attackFund
        // (i.e., no extra changes due to re-entrancy). We observe via the public getter getBalance.
        assertTrue(c.getBalance(address(attacker)) == (ok ? attackFund : 0));
    }
}

// Minimal re-entrant attacker: on receiving ETH it re-enters addToBalance once
contract ReentrantAttacker {
    C immutable target;
    bool sentOnce;
    constructor(address _t) { target = C(_t); }

    // entry point to start the sequence; payable so it can send ETH
    function attack() external payable {
        // first call to addToBalance from this contract
        target.addToBalance{value: msg.value}();
    }

    // re-enter in receive to try to call addToBalance again during the same external invocation
    receive() external payable {
        if (!sentOnce) {
            sentOnce = true;
            // re-enter target.addToBalance with 0 value to attempt to manipulate state if reentrancy not prevented
            // note: sending 0 value still calls the function and may affect internal bookkeeping if flawed
            target.addToBalance{value: 0}();
        }
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    Attacker attacker;

    function setUp() public { c = new C(); attacker = new Attacker(c); }

    // fuzz parameters: attackerDeposit is the amount the attacker seeds and re-enters with,
    // honestDeposit is a later honest depositor amount, honest is the honest depositor address
    function testFuzz_property(uint256 attackerDeposit, uint256 honestDeposit, address honest) public {
        // Keep values in wide but sensible ranges
        attackerDeposit = bound(attackerDeposit, 1, 1 ether);
        honestDeposit = bound(honestDeposit, 1, 1 ether);
        // honest should not be the attacker contract itself
        vm.assume(honest != address(attacker));

        // Fund attacker and honest externally
        vm.deal(address(attacker), attackerDeposit + 0.1 ether);
        vm.deal(honest, honestDeposit + 0.1 ether);

        // Attacker deposits first. Its receive will attempt to re-enter addToBalance during withdrawBalance
        vm.prank(address(attacker));
        c.addToBalance{value: attackerDeposit}();

        // Now have the attacker trigger a withdraw that causes re-entrancy into addToBalance
        // The attacker contract will, during its receive, call addToBalance to re-enter
        vm.prank(address(attacker));
        c.withdrawBalance();

        // Now an honest depositor makes a deposit
        vm.prank(honest);
        c.addToBalance{value: honestDeposit}();

        // The invariant: total of stored balances (for attacker and honest) equals contract ETH balance
        // We can only read via getter getBalance and address(c).balance
        uint balAtt = c.getBalance(address(attacker));
        uint balHon = c.getBalance(honest);
        uint sumStored = balAtt + balHon;
        assertTrue(sumStored == address(c).balance);
    }
}

// Minimal attacker that will re-enter C.addToBalance during withdrawBalance via receive()
contract Attacker {
    C public target;
    bool public reentered;

    constructor(C _t) payable {
        target = _t;
    }

    // On receiving funds during withdrawBalance, attempt to re-enter addToBalance once
    receive() external payable {
        if (!reentered) {
            reentered = true;
            // re-enter with a small amount of value from this contract
            // fund self if needed (but setUp dealt enough)
            target.addToBalance{value: 1 wei}();
        }
    }
}

