pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    // Fuzz params: attacker address atk and deposit amount amt
    // We deploy a small attacker helper that reenters on receive to call addToBalance again.
    // We assume amt is small enough to fund the attacker and nonzero.
    function testFuzz_property(address atk, uint256 amt) public {
        // admissible domain: non-zero amount and a valid attacker EOA address (nonzero)
        vm.assume(atk != address(0));
        vm.assume(amt > 0);
        // limit amt to reasonable bound to avoid out-of-gas or huge balances
        amt = bound(amt, 1, 1 ether);

        // deploy a reentrant helper and fund it
        ReentrantHelper helper = new ReentrantHelper(c);
        // give helper enough ETH to perform the deposit(s)
        vm.deal(address(helper), amt * 2);

        // The helper will, when receiving ETH, attempt to reenter addToBalance once.
        // Perform the deposit from helper into c
        try helper.deposit{value: amt}() {
            // deposit succeeded
        } catch {
            // ignore
        }

        // After the helper's deposit completes (which may have reentered), the reference
        // contract must record at least as much credited to helper as the ETH the helper sent.
        // We assert that c.getBalance(address(helper)) >= amt
        // This is a universal property for the correct contract; the mutant that omits
        // setting locked_ = true can allow reentrancy to cause stored balance to underreport
        // the ETH actually transferred for some inputs, causing this assert to fail.
        uint256 recorded = c.getBalance(address(helper));
        assertTrue(recorded >= amt);
    }
}

// Minimal reentrant helper: on receive, it tries to call addToBalance on C one more time.
contract ReentrantHelper {
    C c;
    bool reentered;
    constructor(C _c) {
        c = _c;
        reentered = false;
    }

    // caller deposits by calling this function with value
    function deposit() external payable {
        // forward the received Ether into C as a user deposit
        // call addToBalance as this contract
        c.addToBalance{value: msg.value}();
    }

    receive() external payable {
        // try to reenter once
        if (!reentered) {
            reentered = true;
            // reenter by calling addToBalance with a small amount if this contract has balance
            uint256 toSend = address(this).balance >= 1 ether ? 1 ether : address(this).balance;
            if (toSend > 0) {
                c.addToBalance{value: toSend}();
            }
        }
    }
}

