pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // Fuzz parameters: depositor (EOA) address and an uint256 deposit amount
    // We will deploy an attacker helper that re-enters when it receives ETH.
    function testFuzz_property(address depositor, uint256 amt) public {
        // Keep depositor as a non-zero, non-contract EOA-like address
        vm.assume(depositor != address(0));
        // Keep amount within reasonable bounds but allow zero too (we allow wide domain)
        amt = bound(amt, 0, 1 ether);

        // Deploy attacker helper that will try to re-enter c.addToBalance when it receives ETH
        ReentrantAttacker attacker = new ReentrantAttacker(address(c));

        // Fund depositor and attacker so they can send ETH
        vm.deal(depositor, amt);
        vm.deal(address(attacker), 1 ether);

        // First, have the attacker deposit some ETH so it becomes able to re-enter later
        // Attacker acts as a normal depositor (this sets up state that attacker may exploit)
        uint256 attackerDeposit = 0.1 ether;
        vm.prank(address(attacker));
        c.addToBalance{value: attackerDeposit}();

        // Now the depositor will call addToBalance with amt while the attacker is waiting to re-enter.
        // To force potential reentrancy interleaving, we have the depositor send a small value and the attacker
        // re-enters on its fallback when it receives ETH from the depositor's call via a malicious low-level call.
        // We arrange for the attacker to try to re-enter during the depositor's addToBalance by having the attacker
        // set itself as a callee that the contract will call: attacker will attempt to call c.addToBalance during its receive.
        attacker.setReenterCount(3); // try multiple re-entries if possible

        // Depositor performs the deposit; if mutant is present (no locked_ = true) attacker may re-enter
        vm.prank(depositor);
        c.addToBalance{value: amt}();

        // single assert: the depositor's stored balance must equal the cumulative ETH they have sent (here just the single deposit amt)
        // This property holds on the correct contract for all inputs: after the single deposit by an EOA, their userBalance equals previously stored + amt.
        // The mutant that omits locked_ = true allows reentrant attacker to alter stored balances so this can fail for some inputs.
        assertTrue(c.getBalance(depositor) == amt);
    }
}

// Minimal reentrant attacker that on receive will try to call back into C.addToBalance
contract ReentrantAttacker {
    C public target;
    uint public reenterCount;

    constructor(address _t) {
        target = C(_t);
    }

    function setReenterCount(uint n) external {
        reenterCount = n;
    }

    receive() external payable {
        // try to re-enter limited times
        if (reenterCount == 0) return;
        reenterCount -= 1;
        // do a small reentrant deposit to attempt to manipulate balances
        // note: attacker must have ETH to send; tests fund this contract
        try target.addToBalance{value: 1 wei}() {
        } catch {
        }
    }
}

