pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzzed params: depositor (EOA), attacker deposit amount for triggering reentrancy, honest deposit amount
    function testFuzz_property(address depositor, uint256 attackerFund, uint256 honestDeposit) public {
        // Keep domain wide but meaningful
        vm.assume(depositor != address(0));
        // bound amounts to reasonable values (non-zero honest deposit)
        honestDeposit = bound(honestDeposit, 1, 1 ether);
        attackerFund = bound(attackerFund, 0, 1 ether);

        // Deploy an attacker that will re-enter when it receives ETH (if funded)
        Attacker atk = new Attacker(c);

        // Fund attacker so it can perform deposits if needed
        if (attackerFund > 0) {
            vm.deal(address(atk), attackerFund);
            // attacker initially deposits to have some stored balance and enable reentrancy path
            vm.prank(address(atk));
            // attacker calls addToBalance to set up potential reentrant behavior state
            c.addToBalance{value: attackerFund}();
        }

        // Record depositor's prior stored balance
        uint256 prior = c.getBalance(depositor);

        // Give depositor ETH and make them call addToBalance as an EOA
        vm.deal(depositor, honestDeposit);
        vm.prank(depositor);
        // Honest depositor performs a single deposit; during this call the attacker (if any) may re-enter
        try c.addToBalance{value: honestDeposit}() {
            // call succeeded
        } catch {
            // if the call reverts, treat as not OK; the invariant we assert below expects successful completion
        }

        // The universal property we assert: for any depositor and admissible attacker funding,
        // after a single honest deposit the depositor's stored balance must have increased by exactly honestDeposit
        // (i.e., stored balance == prior + honestDeposit). The mutant missing locked_ = true allows
        // a reentrant attacker to make this false for some inputs.
        uint256 after = c.getBalance(depositor);
        assertTrue(after == prior + honestDeposit);
    }
}

