    receive() external payable {
        if (!reentered) {
            reentered = true;
            // re-enter target.addToBalance forwarding some or all ETH we have
            // try-catch to avoid bubbling reverts into target's flow
            try target.addToBalance{value: msg.value}() {
            } catch {
            }
        }
    }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single test function: deposit then check getter matches deposited amount
    function run(address user, uint256 depositAmount) public payable {
        // must have enough ether to forward
        require(address(this).balance >= depositAmount);
        // Caller (this test) will simulate the user depositing by calling addToBalance via this contract
        // To make c record under "user", we need to make the call originate from `user`. But we can only call through this contract.
        // Instead, require that `user` is this contract to simulate a deposit from the same address as later queried.
        // Enforce that by requiring user == address(this)
        require(user == address(this));

        // perform deposit into c from this contract
        c.addToBalance{value: depositAmount}();

        // Observe reported balance
        uint256 reported = c.getBalance(user);

        // Also observe contract c's recorded withdrawable balance via address(c).balance
        // The invariant we assert: reported equals the deposited amount (no +1 offset)
        assert(reported == depositAmount);
    }

    // allow this contract to receive Ether
    receive() external payable {}
}

