pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // Fuzz parameters: payer - the address that sends Ether to addToBalance
    //                  querier - the address that calls getBalance
    function testFuzz_property(address payer, address querier, uint256 amount) public {
        // keep addresses non-zero to avoid weird zero-address semantics
        vm.assume(payer != address(0));
        vm.assume(querier != address(0));
        // bound amount to a reasonable value (but keep wide)
        amount = bound(amount, 0, 1 ether);

        // fund payer so they can call payable addToBalance
        vm.deal(payer, amount);
        // payer adds amount to their balance in c
        vm.prank(payer);
        c.addToBalance{value: amount}();

        // Now read the balance for payer via getBalance(payer) as an external caller (querier)
        // The correct contract must return the stored balance of 'payer' regardless of who calls.
        uint balFromView;
        // call as querier to ensure msg.sender in getBalance call is querier
        vm.prank(querier);
        balFromView = c.getBalance(payer);

        // Single assertion: the observed returned balance for queried address 'payer' equals the actual stored balance for that address.
        // We read the actual stored balance via calling getBalance(payer) (the public view) — this is the contract's public surface.
        // The property: c.getBalance(payer) == c.getBalance(payer) trivially holds, but we need to ensure the returned value equals the expected stored value.
        // We can obtain the expected stored value by calling getBalance from the payer itself as well and compare: both should match for the correct contract.
        vm.prank(payer);
        uint balWhenQueriedByOwner = c.getBalance(payer);

        // The invariant: regardless of who calls getBalance(payer), the returned value must be the same (i.e., it depends only on the argument address)
        assertTrue(balFromView == balWhenQueriedByOwner);
    }
}

