pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // Fuzz parameters: an address `actor` and an amount `amt` to fund that actor.
    // General rule: for any actor, getBalance(actor) == the balance stored for that actor.
    // The mutant returns the balance of address(0) instead, so when actor != address(0)
    // and the actor's balance differs from address(0)'s balance, the mutant will fail.
    function testFuzz_property(address actor, uint256 amt) public {
        // keep actor wide but avoid zero-address for the primary actor to allow distinguishing
        vm.assume(actor != address(0));
        // bound amount to a reasonable size so vm.deal works in fuzzing
        amt = bound(amt, 0, 1 ether);

        // ensure actor has `amt` ETH
        vm.deal(actor, amt);
        // actor adds to their balance in the contract
        vm.prank(actor);
        c.addToBalance{value: amt}();

        // Now read via the public getter getBalance
        uint balForActor = c.getBalance(actor);
        uint balForZero = c.getBalance(address(0));

        // The universal property the reference satisfies: when actor != address(0),
        // getBalance(actor) equals the stored balance for that actor, which should be
        // different from getBalance(address(0)) whenever we actually funded the actor
        // and did not fund address(0). We assert that either the balances are equal
