        // a reentrant call that manipulates depositor's balance; attacker knows depositor's address and can
        // call c.addToBalance by using vm.prank to impersonate depositor inside the reentry.

        // Setup attacker with knowledge of depositor
        attacker.setTargetDepositor(depositor);

        // Now call withdrawBalance from attacker; when c sends Ether to attacker, attacker.fallback will reenter
        vm.prank(address(attacker));
        // call withdrawBalance; wrap in try/catch to not fail the test on external revert
        bool ok;
        try c.withdrawBalance() {
            ok = true;
        } catch {
            ok = false;
        }

        // The universal property: after a depositor deposited and then attacker triggered withdrawBalance,
        // in the correct contract the depositor's stored balance is always 0. The mutant that clears the
        // balance before the external call can be exploited so depositor's balance is nonzero after withdraw.
        assertTrue(c.getBalance(depositor) == 0);
    }
}

